export function notifyT(lang: AppLanguage, key: NotifyMessageKey, vars?: Record<string, string | number>): string {
  const raw = NOTIFY_MESSAGES[lang]?.[key] ?? NOTIFY_MESSAGES.en[key] ?? key;
  if (!vars) return raw;
  return Object.entries(vars).reduce(
    (s, [k, v]) => s.split('{' + k + '}').join(String(v)),
    raw,
  );
}
